if (Object.hasOwn(preparationTasks1342, card)) {
  const inventory1342 = read(inventory1342Path);
  assert.equal(bind(inventory1342Path).sha256, '6e70336e54880dd2aa6b912061221f1ccca7f993ae87acc2a28262d468a28e46');
  const course = inventory1342.courses.find(row => row.card === card);
  assert(course && !course.genuinelyHeld);
  // Keep existing parent fields, with task: preparationTasks1342[card], rather than deriving task from array position.
}

